class TypedMetadataValue{public string Value;public override bool Equals(object other)=>other is TypedMetadataValue t&&t.Value==Value;public override int GetHashCode()=>Value?.GetHashCode()??0;}class Stat{}
class ItemValue{public int type=1,Meta;public float UseTimes;public ushort Seed=10,Quality=2;public byte SelectedAmmoTypeIndex;public bool Activated;public Stat[] Stats;public Dictionary<string,TypedMetadataValue> Metadata;public ItemValue[] modifications,cosmeticMods;public bool IsEmpty()=>type==0;public ItemValue Clone(){var c=(ItemValue)MemberwiseClone();c.Metadata=Metadata==null?null:Metadata.ToDictionary(p=>p.Key,p=>new TypedMetadataValue{Value=p.Value.Value});c.modifications=modifications?.Select(i=>i?.Clone()).ToArray();c.cosmeticMods=cosmeticMods?.Select(i=>i?.Clone()).ToArray();return c;}
